using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

// ── Bootstrap ────────────────────────────────────────────────────────────────
var builder = Host.CreateApplicationBuilder(args);

builder.Logging.SetMinimumLevel(LogLevel.Warning);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? builder.Configuration["AI:ApiKey"]
    ?? throw new InvalidOperationException(
        "Set OPENAI_API_KEY env var or AI:ApiKey in appsettings/user-secrets.");

const string modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

// ── Resolve services ─────────────────────────────────────────────────────────
var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

// ── Build the agent ──────────────────────────────────────────────────────────
var agent = new ChatClientAgent(chatClient,
    """
    You are a research agent. Your job is to research a topic the user gives you.

    Workflow:
    1. Break the topic into 2-3 focused search queries.
    2. Use the WebSearch tool for each query.
    3. Use the SaveNote tool to record each key finding (cite the source).
    4. After gathering enough information, use GetNotes to review all your notes.
    5. Provide a final summary to the user with key findings and sources.

    Be thorough but concise. Always cite sources.
    """)
{
    Name = "ResearchAgent",
    Tools = [.. AIFunctionFactory.Create(tools)],
};

// ── Run ──────────────────────────────────────────────────────────────────────
Console.WriteLine("🔬 Research Agent Ready");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research this topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

// ── Tools ────────────────────────────────────────────────────────────────────
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "application/json" },
        },
    };

    [Description("Search the web for information on a query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public async Task<string> WebSearch(
        [Description("The search query string")] string query,
        [Description("Max number of results to return (1-5)")] int maxResults = 3)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await _httpClient.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<object>();

            // Instant answer
            if (root.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
            {
                var source = root.TryGetProperty("AbstractURL", out var aUrl) ? aUrl.GetString() : "";
                results.Add(new { Title = "Summary", Snippet = abstractText, Url = source });
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray())
                {
                    if (results.Count >= maxResults) break;

                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        var itemUrl = item.TryGetProperty("FirstURL", out var fu) ? fu.GetString() : "";
                        results.Add(new { Title = "Related", Snippet = t, Url = itemUrl });
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try a different search query.";
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a source citation. Use this to record key findings.")]
    public string SaveNote(
        [Description("The key finding or fact to record")] string note,
        [Description("The source URL or reference")] string source)
    {
        var entry = $"• {note} [Source: {source}]";
        _notes.Add(entry);
        return $"Note saved ({_notes.Count} total).";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return $"=== Research Notes ({_notes.Count}) ===\n{string.Join("\n", _notes)}";
    }
}

