using System.ComponentModel;
using System.Net;
using System.Reflection;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ────────────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

const string modelId = "gpt-4o-mini-2024-07-18";

// ── Build AI tools ───────────────────────────────────────────────────────────
var researchTools = new ResearchTools();

var toolList = typeof(ResearchTools)
    .GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
    .Where(m => m.GetCustomAttribute<DescriptionAttribute>() is not null)
    .Select(m => (AITool)AIFunctionFactory.Create(m, researchTools))
    .ToList();

// ── Build the chat client ────────────────────────────────────────────────────
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// ── Build the agent ──────────────────────────────────────────────────────────
var agent = new ChatClientAgent(
    chatClient: chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic the user gives you.

        Workflow:
        1. Break the topic into 2-3 focused search queries.
        2. Use the WebSearch tool for each query.
        3. Use the SaveNote tool to record each key finding (cite the source).
        4. After gathering enough information, use GetNotes to review all your notes.
        5. Provide a final summary to the user with key findings and sources.

        Be thorough but concise. Always cite sources.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: toolList);

// ── Run ──────────────────────────────────────────────────────────────────────
Console.WriteLine("🔬 Research Agent Ready");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync();

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

await foreach (var update in agent.RunStreamingAsync(
    $"Research this topic and provide a summary: {topic}", session, runOptions))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();

