 // ── Tools ────────────────────────────────────────────────────────────────────
 public sealed class ResearchTools
 {
     private readonly List<string> _notes = [];
     private readonly HttpClient _httpClient = new()
     {
         DefaultRequestHeaders =
         {
             { "User-Agent", "ResearchAgent/1.0" },
             { "Accept", "application/json" },
         },
     };

     [Description("Search the web for information on a query. Returns a list of relevant results with titles, snippets, and URLs.")]
     public async Task<string> WebSearch(
         [Description("The search query string")] string query,
         [Description("Max number of results to return (1-5)")] int maxResults = 3)
     {
         maxResults = Math.Clamp(maxResults, 1, 5);

         try
         {
             var encoded = WebUtility.UrlEncode(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var json = await _httpClient.GetStringAsync(url);

             using var doc = JsonDocument.Parse(json);
             var root = doc.RootElement;

             var results = new List<object>();

             // Instant answer
             if (root.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
             {
                 var source = root.TryGetProperty("AbstractURL", out var aUrl) ? aUrl.GetString() : "";
                 results.Add(new { Title = "Summary", Snippet = abstractText, Url = source });
             }

             // Related topics
             if (root.TryGetProperty("RelatedTopics", out var topics))
             {
                 foreach (var item in topics.EnumerateArray())
                 {
                     if (results.Count >= maxResults) break;

                     if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                     {
                         var itemUrl = item.TryGetProperty("FirstURL", out var fu) ? fu.GetString() : "";
                         results.Add(new { Title = "Related", Snippet = t, Url = itemUrl });
                     }
                 }
             }

             if (results.Count == 0)
             {
                 return $"No results found for '{query}'. Try a different search query.";
             }

             return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }

     [Description("Save a research note with a source citation. Use this to record key findings.")]
     public string SaveNote(
         [Description("The key finding or fact to record")] string note,
         [Description("The source URL or reference")] string source)
     {
         var entry = $"• {note} [Source: {source}]";
         _notes.Add(entry);
         return $"Note saved ({_notes.Count} total).";
     }

     [Description("Retrieve all saved research notes collected so far.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         return $"=== Research Notes ({_notes.Count}) ===\n{string.Join("\n", _notes)}";
     }
